effect.shader:
        void main() {
            // Normalized screen coordinates (0 to 1)
            vec2 uv = acScreenNorm;

            // Fix aspect ratio so the spot is a perfect circle
            float aspect = acScreenSize.x / acScreenSize.y;
            vec2 p = uv;
            p.x *= aspect;

            // Handle center position
            vec2 m = vec2(centerX, centerY);
            m.x *= aspect;

            // Calculate distance from center
            float dist = length(p - m);

            // Create the spot mask using smoothstep for softness
            // 1.0 inside the spot, falling off to 0.0 outside
            float spotMask = smoothstep(spotRadius + spotSoftness, spotRadius, dist);

            // Sample the input channel
            vec4 texColor = texture2DCv(inputImg.texture, uv);

            // Calculate final exposure
            // Mixes between Base Exposure and (Base + Boost) based on the mask
            float currentExposure = exposure + (spotBoost * spotMask);

            // Apply exposure to the color (preserving alpha)
            vec3 finalColor = texColor.rgb * currentExposure;

            // Output to screen
            gl_FragColor = vec4(finalColor, texColor.a);
        }
